    description: string;
    direction: TransactionsTransactionDirection;
    /**
     * The amount in the display currency the device sent (X-Display-Currency), converted at today's rate and rounded to cents; null when that is the account currency, none was sent or there is no rate. Clients show it first and amount as the second line.
     */
    display?: OccurrenceDisplay | null;
    frequency: Frequency;
    /**
     * True when the date is today or earlier in the user's zone: the hourly processor posts the occurrence on its next run.
     */
    is_due: boolean;
    merchant?: string | null;
    /**
     * The enriched merchant identity of the rule, when known.
     */
    merchant_brand?: BrandResponse | null;
    /**
     * The rule's: confirm, post (the server writes the operation) or track_only (it waits for the account's own row).
     */
    mode: Mode;
    note?: string | null;
    /**
     * The business project the rule's operations get.
     */
    project_id?: string | null;
    rule_id: string;
    /**
     * Planned (still ahead, or waiting within its window), awaiting_confirmation (a confirm rule's payment day came and nobody confirmed or skipped it yet: never paid, never spent), paid, skipped, missing (a track_only payment whose window closed with no row) or paused (the rule was paused on that day). Past items come only with with_past.
     */
    status: OccurrenceStatus;
    /**
     * The row that settled the occurrence (paid), when known.
     */
    transaction_id?: string | null;
    type: TransactionsTransactionType;
    /**
     * The last day a track_only rule waits for the row (null for post).
     */
